// Modern HD 2D Chibi 18-кадровый 8-направленный спрайт-лист героя NOCTIS (4 кадра на каждую диагональ!)
import type { WeaponDef } from './data';

export interface PlayerSpriteBank {
  ready: boolean;
  idle: HTMLImageElement;
  run: HTMLImageElement[];
  up: HTMLImageElement[];
  down: HTMLImageElement[];
  upDiag: HTMLImageElement[];
  downDiag: HTMLImageElement[];
  atk1: HTMLImageElement;
  atk2: HTMLImageElement;
  dash: HTMLImageElement;
}

const DATA: Record<string, string> = {"run0": "data:image/webp;base64,", "run1": "data:image/webp;base64,", "run2": "data:image/webp;base64,", "run3": "data:image/webp;base64,", "idle": "data:image/webp;base64,", "atk1": "data:image/webp;base64,", "atk2": "data:image/webp;base64,", "dash": "data:image/webp;base64,", "up0": "data:image/webp;base64,", "down0": "data:image/webp;base64,", "upDiag0": "data:image/webp;base64,", "upDiag1": "data:image/webp;base64,", "upDiag2": "data:image/webp;base64,", "upDiag3": "data:image/webp;base64,", "downDiag0": "data:image/webp;base64,", "downDiag1": "data:image/webp;base64,", "downDiag2": "data:image/webp;base64,", "downDiag3": "data:image/webp;base64,", "up1": "data:image/webp;base64,", "down1": "data:image/webp;base64,", "up2": "data:image/webp;base64,", "down2": "data:image/webp;base64,", "up3": "data:image/webp;base64,", "down3": "data:image/webp;base64,"};
let bank: PlayerSpriteBank | null = null;
const tintedCache = new Map<string, HTMLCanvasElement>();

function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace('#', '');
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const n = parseInt(h.slice(0, 6), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

export function getWeaponTintedFrame(
  img: HTMLImageElement,
  frameKey: string,
  w: WeaponDef,
): HTMLCanvasElement | HTMLImageElement {
  if (w.id === 'rusty' || w.id === 'frost' || !img.complete || img.naturalWidth === 0) return img;
  const cacheKey = `${frameKey}_${w.id}`;
  const hit = tintedCache.get(cacheKey);
  if (hit) return hit;

  const cv = document.createElement('canvas');
  cv.width = img.naturalWidth;
  cv.height = img.naturalHeight;
  const ctx = cv.getContext('2d');
  if (!ctx) return img;

  ctx.drawImage(img, 0, 0);
  const imgData = ctx.getImageData(0, 0, cv.width, cv.height);
  const d = imgData.data;
  const [tr, tg, tb] = hexToRgb(w.c.glow || w.c.edge);
  const [er, eg, eb] = hexToRgb(w.c.edge || w.c.blade);

  for (let i = 0; i < d.length; i += 4) {
    if (d[i + 3] < 40) continue;
    const r = d[i], g = d[i + 1], b = d[i + 2];
    const luma = 0.299 * r + 0.587 * g + 0.114 * b;
    const isCyanBlade = (g > 155 && b > 155 && g + b > r * 1.55) || (luma > 212 && Math.max(r, g, b) - Math.min(r, g, b) < 40);
    if (isCyanBlade) {
      const k = Math.min(1, (luma - 120) / 120);
      d[i] = Math.min(255, Math.round((er * (1 - k * 0.45) + tr * (k * 0.45)) * (0.72 + k * 0.48)));
      d[i + 1] = Math.min(255, Math.round((eg * (1 - k * 0.45) + tg * (k * 0.45)) * (0.72 + k * 0.48)));
      d[i + 2] = Math.min(255, Math.round((eb * (1 - k * 0.45) + tb * (k * 0.45)) * (0.72 + k * 0.48)));
    }
  }
  ctx.putImageData(imgData, 0, 0);
  tintedCache.set(cacheKey, cv);
  return cv;
}

export function getPlayerSprites(): PlayerSpriteBank {
  if (bank) return bank;
  let loaded = 0;
  let total = 0;
  const mk = (key: string): HTMLImageElement => {
    total++;
    const img = new Image();
    img.onload = () => {
      loaded++;
      if (loaded >= total && bank) bank.ready = true;
    };
    img.src = DATA[key];
    return img;
  };
  bank = {
    ready: false,
    idle: mk('idle'),
    run: [mk('run0'), mk('run1'), mk('run2'), mk('run3')],
    up: [mk('up0'), mk('up1'), mk('up2'), mk('up3')],
    down: [mk('down0'), mk('down1'), mk('down2'), mk('down3')],
    upDiag: [mk('upDiag0'), mk('upDiag1'), mk('upDiag2'), mk('upDiag3')],
    downDiag: [mk('downDiag0'), mk('downDiag1'), mk('downDiag2'), mk('downDiag3')],
    atk1: mk('atk1'),
    atk2: mk('atk2'),
    dash: mk('dash'),
  };
  return bank;
}
